Rules.InvariantScript:
// ============================================================
// scr_MyActivities.OnVisible — PRODUCTION VERSION
// Purpose: initialise filter state and load user's assigned activities
// with their latest report status for the current reporting period
// ============================================================

// ------------------------------------------------------------
// 1. FILTER STATE — reset every visit
// ------------------------------------------------------------
Set(varActFilterFY, varCurrentFY);
Set(varActFilterMonth, "All");
Set(varActFilterStatus, "All");

// ------------------------------------------------------------
// 2. LOAD MY ACTIVITIES — this user's own assigned activities
// ------------------------------------------------------------
ClearCollect(
    colMyActivities,
    Filter(Activities, ActivityOwner.Email = varUserEmail, 'Active ' = true)
);

// ------------------------------------------------------------
// 3. BUILD ACTIVITY STATUS — join each activity with its latest
//    report for the selected FY/month, derive RAG and action label
// ------------------------------------------------------------
ClearCollect(
    colMyActivityStatus,
    ForAll(
        colMyActivities As Act,
        With(
            {
                latestReport: First(
                    Filter(
                        MonthlyReports,
                        Activity.Id = Act.ID,
                        'FinancialYear '.Value = varCurrentFY,
                        ActivityOwner.Email = varUserEmail
                    )
                )
            },
            {
                ActivityID: Act.ID,
                ActivityName: Act.'Activity: ActivityShortDescription'.Value,
                ProjectName: Act.Project.Value,
                ProgrammeName: Act.ProgrammeLabel,
                DirectorateName: Act.DirectorateLabel,
                Frequency: Act.'Frequency ',
                DueDay: Act.DueDay,
                ReportStatus: Coalesce(latestReport.Status.Value, "Not Started"),
                ReportID: Coalesce(latestReport.ID, Blank()),
                RAG: Switch(
                    Coalesce(latestReport.Status.Value, "Not Started"),
                    "Approved", "Green",
                    "Draft", "Amber",
                    "Submitted", "Amber",
                    "Rejected", "Red",
                    "Green"
                ),
                ActionLabel: Switch(
                    Coalesce(latestReport.Status.Value, "Not Started"),
                    "Not Started", "Start Report",
                    "Draft", "Continue",
                    "Submitted", "Submitted ✓",
                    "Rejected", "Resubmit",
                    "Approved", "View",
                    "Start Report"
                ),
                ActionDisabled: Coalesce(latestReport.Status.Value, "Not Started") = "Submitted",
                IsOverdue: Coalesce(latestReport.IsOverdue, false),
                IsFlagged: Coalesce(latestReport.isFlagged, false)
            }
        )
    )
);

// ------------------------------------------------------------
// 4. SET RESULT COUNT
// ------------------------------------------------------------
Set(varActResultCount, CountRows(colMyActivityStatus));

// ============================================================
// END OF scr_MyActivities.OnVisible
// ============================================================

